UPDATE catalogs SET data=(
 SELECT json_group_array(json(CASE WHEN EXISTS(SELECT 1 FROM updates u WHERE json_extract(u.patch,'$.image')=json_extract(m.value,'$.image')) THEN
  json_set(m.value,'$.parts',json((SELECT json_group_array(json(CASE WHEN u.patch IS NOT NULL
   AND json_extract(p.value,'$.name')=json_extract(u.patch,'$.oldName')
   AND json_extract(p.value,'$.nameStatus')=json_extract(u.patch,'$.oldStatus')
   THEN json_set(p.value,'$.name',json_extract(u.patch,'$.name'),'$.nameStatus','web_catalog','$.nameEvidence',json_extract(u.patch,'$.nameEvidence'),'$.nameSource',json_extract(u.patch,'$.nameSource'),'$.needsReview',json('true'))
   ELSE p.value END)) FROM json_each(m.value,'$.parts') p LEFT JOIN updates u ON json_extract(u.patch,'$.image')=json_extract(m.value,'$.image') AND json_extract(u.patch,'$.id')=json_extract(p.value,'$.id')))) ELSE m.value END)) FROM json_each(catalogs.data) m
),revision=revision+1 WHERE id='main' AND EXISTS(
 SELECT 1 FROM json_each(catalogs.data) m, json_each(m.value,'$.parts') p, updates u
 WHERE json_extract(m.value,'$.image')=json_extract(u.patch,'$.image') AND json_extract(p.value,'$.id')=json_extract(u.patch,'$.id')
 AND json_extract(p.value,'$.name')=json_extract(u.patch,'$.oldName') AND json_extract(p.value,'$.nameStatus')=json_extract(u.patch,'$.oldStatus')
);
